function threeSum(nums) {
  // Fix the smallest value, then find pairs with a hash set; dedupe by key.
  const a = nums.slice().sort((x, y) => x - y);
  const seen = new Set();
  const out = [];
  for (let i = 0; i < a.length; i++) {
    if (i > 0 && a[i] === a[i - 1]) continue;
    const earlier = new Set();
    for (let j = i + 1; j < a.length; j++) {
      const need = -a[i] - a[j];
      if (earlier.has(need)) {
        const key = a[i] + ',' + need + ',' + a[j];
        if (!seen.has(key)) { seen.add(key); out.push([a[i], need, a[j]]); }
      }
      earlier.add(a[j]);
    }
  }
  return out;
}

